export function rebaseMentions(before,after,entries){let start=0;while(start<before.length&&start<after.length&&before[start]===after[start])start++;let end=before.length,next=after.length;while(end>start&&next>start&&before[end-1]===after[next-1]){end--;next--}const delta=next-end;return entries.flatMap(item=>{if(item.start+item.label.length<=start)return[item];if(item.start>=end)return[{...item,start:item.start+delta}];return[]})}
export function mentionAttachment(text,entries,members,prefix=''){const ids=new Set(members.map(m=>String(m.user_id))),kept=entries.filter(e=>typeof e.label==='string'&&Number.isInteger(e.start)&&e.start>=0&&ids.has(String(e.id))&&text.slice(e.start,e.start+e.label.length)===e.label).slice(0,30);return kept.length?{type:'mentions',user_ids:kept.map(e=>String(e.id)),loci:kept.map(e=>[prefix.length+e.start,e.label.length])}:null}
